-- MySQL >= 8.0.16 / InnoDB (tested on 8.0.46). Execute in an empty, explicitly selected database.
-- UUIDs are generated by Node crypto.randomUUID(); internal numeric IDs never leave the API.
CREATE TABLE `Role` (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  internalUUID CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  code VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name VARCHAR(60) NOT NULL,
  PRIMARY KEY (id), UNIQUE KEY uq_role_uuid (internalUUID), UNIQUE KEY uq_role_code (code),
  CONSTRAINT ck_role_code CHECK (code IN ('USER','COMPANY','ADMIN'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

