CREATE TABLE `User` (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  internalUUID CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  roleCode VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'USER',
  displayName VARCHAR(120) NOT NULL,
  email VARCHAR(254) NOT NULL,
  passwordHash VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  accountStatus VARCHAR(12) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'ACTIVE',
  verificationStatus VARCHAR(14) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'PENDING',
  verificationDocumentKey VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin NULL,
  tokenVersion INT UNSIGNED NOT NULL DEFAULT 0,
  createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updatedAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  deletedAt DATETIME(3) NULL,
  PRIMARY KEY (id), UNIQUE KEY uq_user_uuid (internalUUID), UNIQUE KEY uq_user_email (email),
  CONSTRAINT fk_user_role FOREIGN KEY (roleCode) REFERENCES `Role` (code) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT ck_user_status CHECK (accountStatus IN ('ACTIVE','SUSPENDED')),
  CONSTRAINT ck_user_verification CHECK (
    (roleCode = 'COMPANY' AND verificationStatus IN ('PENDING','APPROVED','REJECTED')
      AND verificationDocumentKey IS NOT NULL AND CHAR_LENGTH(verificationDocumentKey) > 0)
    OR (roleCode IN ('USER','ADMIN') AND verificationStatus = 'NOT_REQUIRED' AND verificationDocumentKey IS NULL)
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `Publication` (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  internalUUID CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  ownerId BIGINT UNSIGNED NOT NULL,
  materialType VARCHAR(10) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  quantityKg DECIMAL(10,3) NOT NULL,
  locationText VARCHAR(300) NOT NULL,
  availabilityText VARCHAR(200) NOT NULL,
  photoJpeg MEDIUMBLOB NOT NULL,
  status VARCHAR(12) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'disponible',
  createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updatedAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  deletedAt DATETIME(3) NULL,
  PRIMARY KEY (id), UNIQUE KEY uq_publication_uuid (internalUUID),
  KEY ix_publication_owner (ownerId, deletedAt, createdAt),
  KEY ix_publication_status (status, deletedAt, createdAt),
  CONSTRAINT fk_publication_owner FOREIGN KEY (ownerId) REFERENCES `User` (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT ck_publication_material CHECK (materialType IN ('plastico','papel','vidrio','metal','organico')),
  CONSTRAINT ck_publication_quantity CHECK (quantityKg > 0 AND quantityKg <= 9999999.999),
  CONSTRAINT ck_publication_location CHECK (CHAR_LENGTH(TRIM(locationText)) BETWEEN 3 AND 300),
  CONSTRAINT ck_publication_availability CHECK (CHAR_LENGTH(TRIM(availabilityText)) BETWEEN 3 AND 200),
  CONSTRAINT ck_publication_photo CHECK (OCTET_LENGTH(photoJpeg) BETWEEN 4 AND 1048576),
  CONSTRAINT ck_publication_status CHECK (status IN ('disponible','aceptada','confirmada'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
